            spy_today = self.spy_closes[0]
            spy_yesterday = self.spy_closes[1]
            sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
            sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

            if spy_yesterday <= sma_yesterday and spy_today > sma_today:
                shares = math.floor(
                    0.40 * self.Portfolio.TotalPortfolioValue / float(spy_bar.Close)
                )
                if shares > 0:
                    self.MarketOrder(self.symbols["SPY"], shares)
                    self.strategy_a_shares = shares

        if (
            self.strategy_b_shares == 0
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
