            self.spy_closes[1] <= previous_spy_sma
            and spy_close > current_spy_sma
        )
        spy_crosses_below_sma = (
            self.spy_closes[1] >= previous_spy_sma
            and spy_close < current_spy_sma
        )

        # Evaluate all sells before any buys.
        if self.lots["strategy_a"] > 0 and spy_crosses_below_sma:
            self.MarketOrder(
                self.spy,
                -self.lots["strategy_a"],
                tag="Strategy A: sell entire private lot"
            )
            self.lots["strategy_a"] = 0

        if self.lots["strategy_b"] > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(
                self.aapl,
                -self.lots["strategy_b"],
                tag="Strategy B: sell entire private lot"
            )
            self.lots["strategy_b"] = 0

        if self.lots["strategy_a"] == 0 and spy_crosses_above_sma:
            quantity = int(
                0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close
            )

            if quantity > 0:
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A: invest 40% of portfolio"
                )
                self.lots["strategy_a"] = quantity

        if self.lots["strategy_b"] == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 / aapl_close)

                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B: buy $20,000 if available"
                    )
                    self.lots["strategy_b"] = quantity

